(function(){
  'use strict';
  const api=window.FrameUI,P=window.FramePlanner,$=id=>document.getElementById(id),esc=window.FrameExport.xml;
  const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString('ko-KR',{maximumFractionDigits:d}):'—';
  let step=1,projectId=null,helpers=null,transitioning=false;
  const getMode=()=>api.getProject().ui?.inputMode==='detailed'?'detailed':'simple';
  const count=(path,label,p)=>{const [face,axis]=path.split('.');return `<div class="frame-count-field" data-part-field="${path}"><label class="field frame-part-label ${axis}" for="frame-count-${face}-${axis}">${label}</label><div class="frame-count-controls"><button type="button" data-frame-count-adjust="${path}" data-delta="-1" aria-label="${label} 1개 줄이기">−</button><input id="frame-count-${face}-${axis}" data-count="${path}" data-label="${label}" type="number" min="0" max="100" step="1" inputmode="numeric" value="${p[face][axis].length}" required><button type="button" data-frame-count-adjust="${path}" data-delta="1" aria-label="${label} 1개 늘리기">＋</button></div><span class="field-error" id="frame-count-${face}-${axis}-error" hidden></span></div>`;};
  function drawing(){return `<aside class="frame-drawing-card"><div class="section-line"><h2 data-frame-preview-title>입력한 구조물 3D</h2><span>1대 기준</span></div>${window.Frame3D?window.Frame3D.markup():''}<div id="frame-simple-diagram" class="frame-flat-diagram"></div><p id="frame-live-size"></p><details class="frame-model-note"><summary>그림 표시 기준</summary><p>부재의 바깥 크기를 표시한 그림입니다. 단면 속과 접합 상세는 생략합니다.</p></details></aside>`;}
  function shapePicture(two){return `<svg viewBox="0 0 180 100" aria-hidden="true"><g fill="none" stroke-linejoin="round" stroke-width="5">${two?'<path d="M35 20L160 32L160 86L35 74Z" stroke="#6faaa5"/><path d="M18 32L35 20M145 44L160 32M145 98L160 86M18 86L35 74" stroke="#6cbce6"/>':''}<path d="M18 32L145 44L145 98L18 86Z" stroke="#16947e"/><path d="M60 36L60 90M102 40L102 94" stroke="#c57518"/><path d="M18 59L145 71" stroke="#8066bd"/></g></svg>`;}
  function sizeView(p,r,h){
    const two=p.general.planes===2,c=p.cabinet,derived=c.enabled?{width:c.width*c.columns,height:c.height*c.rows}:p.general;
    return `<div class="frame-size-layout"><section class="frame-wizard-panel"><h2>먼저 모양을 골라주세요.</h2><div class="frame-shape-options" role="group" aria-label="구조물 모양">${[[1,'한 겹 프레임','앞면 한 장으로 제작'],[2,'깊이가 있는 프레임','앞뒤 프레임을 연결']].map(([value,label,note])=>`<button type="button" data-frame-shape="${value}" aria-pressed="${p.general.planes===value}">${shapePicture(value===2)}<strong>${label}</strong><span>${note}</span></button>`).join('')}</div><div hidden>${h.select('general.planes','프레임 구성',[[1,'단면'],[2,'앞뒤 + 좌우 측면']])}</div><div class="fields frame-size-fields">${h.field('general.width','가로 (mm)',{disabled:c.enabled,value:derived.width})}${h.field('general.height','세로 (mm)',{disabled:c.enabled,value:derived.height})}${two?h.field('general.depth','앞뒤 두께 (mm)'):''}${h.field('general.quantity','만들 수량 (대)')}</div><p class="hint">예: 가로 4m는 4,000mm로 입력하세요. ${two?'앞뒤 두께는 프레임 전체의 바깥 치수입니다.':''}</p>${!p.general.extraEquipment&&!(c.enabled&&c.weightEach>0)?'<p class="frame-weight-missing" role="note"><strong>전광판 제품 무게가 0kg입니다.</strong> 기초 계산에 그대로 쓰면 제품 무게가 빠집니다. 아래 ‘전광판 제품 무게’ 또는 ‘캐비닛 개당 무게’에 입력하세요.</p>':''}<details id="frame-equipment-settings" ${p.general.extraEquipment?'open':''}><summary>전광판 제품 무게 ${p.general.extraEquipment?'· '+fmt(p.general.extraEquipment)+'kg/대':'입력'}</summary>${h.field('general.extraEquipment','제품과 기타 장비 무게 (kg/대)')}<p class="hint">프레임은 자동 계산합니다. 여기에 전광판 제품과 장비의 무게를 더하세요. 아래 캐비닛 무게를 사용하면 같은 무게를 중복 입력하지 마세요.</p></details><details id="frame-cabinet-settings" ${c.enabled?'open':''}><summary>캐비닛 개수로 크기·무게 입력 ${c.enabled?'· 사용 중':''}</summary>${h.check('cabinet.enabled','캐비닛 크기와 배열 사용')}<div class="fields">${h.field('cabinet.width','캐비닛 가로 (mm)')}${h.field('cabinet.height','캐비닛 세로 (mm)')}${h.field('cabinet.columns','가로 배열 (열)')}${h.field('cabinet.rows','세로 배열 (행)')}${h.field('cabinet.weightEach','캐비닛 개당 무게 (kg)')}</div>${h.button('cabinet-grid','캐비닛 경계에 보강재 배치')}</details><div class="frame-wizard-actions"><button id="frame-next" type="button" class="button primary">다음 · 자재와 보강 선택 →</button></div></section>${drawing()}</div>`;
  }
  function extraView(p,h){return `<details id="frame-extra-settings" class="frame-wizard-panel"><summary>지주·받침·추가 부재 ${p.extras.length}종</summary><p class="hint">지주와 받침대는 자동으로 추가되지 않습니다. 실제 제작 길이와 대당 개수를 입력하세요.</p>${p.extras.map((x,i)=>`<div class="editable-row">${h.field('extras.'+i+'.name','부재명',{type:'text'})}${h.refFields('extras.'+i,'자재')}${h.field('extras.'+i+'.length','길이 (mm)')}${h.field('extras.'+i+'.quantity','수량 (개/대)')}${h.button('remove-extra','삭제',`data-index="${i}"`)}</div>`).join('')||'<p class="empty">등록한 추가 부재가 없습니다.</p>'}${h.button('add-extra','＋ 지주·추가 부재')}</details>`;}
  function memberView(p,r,h){
    const m=p.materials[0],two=p.general.planes===2,refs=[...Object.values(p.front.edges),...p.front.vertical,...p.front.horizontal,...(two?[...Object.values(p.back.edges),...p.back.vertical,...p.back.horizontal,p.left.top,p.left.bottom,...p.left.vertical,...p.left.horizontal,p.right.top,p.right.bottom,...p.right.vertical,...p.right.horizontal]:[])];
    const mixed=refs.some(x=>x.materialId!==m.id||x.rotation!==0||x.position!==undefined&&x.position!==null);
    const price=m.priceMode==='kg'?h.field('materials.0.pricePerKg','kg당 자재 단가 (원)',{nullable:true,placeholder:'미입력'}):m.stockMode==='mixed'?m.stocks.map((x,i)=>h.field('materials.0.stocks.'+i+'.price',fmt(x.length,0)+'mm 본당 단가 (원)',{nullable:true,placeholder:'미입력'})).join(''):h.field('materials.0.stocks.'+Math.max(0,m.stocks.findIndex(x=>x.length===m.selectedLength))+'.price','선택 길이 본당 단가 (원)',{nullable:true,placeholder:'미입력'});
    const purchasing=[m.stockMode==='mixed'?'혼합 구매 적용 중: '+m.stocks.map(x=>fmt(x.length,0)+'mm').join(' · '):'',p.inventory.length?'보유 원자재·잔재 '+p.inventory.length+'종 사용 중':'',Object.values(p.splices).some(x=>x.mode!=='auto')?'부재별 분할·이음 설정 적용 중':''].filter(Boolean).join('. ');
    return `<div class="frame-size-layout"><section class="frame-wizard-panel"><h2>자재를 고르고, 보강 개수를 조절하세요.</h2><div class="fields">${h.select('materials.0.section','기본 자재 규격',[...Object.entries(P.legacy.presets).map(([id,x])=>[id,`${P.legacy.families[x.family]} ${x.label}`]),['custom','직접 입력']])}</div><p class="hint">규격을 고르면 자재의 무게는 자동으로 채워집니다. 선택한 규격은 첫 자재에 적용됩니다.</p><div class="frame-reinforcement-controls">${count('front.vertical','세로 보강 · 주황색 (개)',p)}${count('front.horizontal','가로 보강 · 보라색 (줄)',p)}</div><p class="hint">＋ / −로 조절하거나 숫자를 입력하세요. 그림의 보강재를 누르면 해당 입력칸으로 이동합니다.</p>${two?`<p id="frame-depth-tie-summary" class="frame-auto-summary" role="status"></p><details id="frame-side-settings"><summary>옆면 보강·앞뒤 연결 설정</summary><div class="frame-reinforcement-controls">${count('left.vertical','옆면 세로 보강 (개)',p)}${count('left.horizontal','옆면 가로 보강 (줄)',p)}</div>${h.check('backLinked','뒷면을 앞면과 동일하게')}${h.check('rightLinked','오른쪽을 왼쪽과 동일하게')}${h.check('general.verticalDepthTies','세로 보강재 위·아래 앞뒤 연결재 자동 추가')}<p id="frame-depth-tie-info" class="frame-guidance"></p></details>`:''}${mixed||two&&(!p.backLinked||!p.rightLinked)?'<p class="frame-guidance">부재마다 다른 규격·위치 또는 독립 면 설정이 있습니다. 기존 설정을 유지합니다. 상세 입력에서 확인하세요.</p>':''}<details id="frame-basic-settings" ${m.section==='custom'?'open':''}><summary>자재 치수·무게 직접 수정 ${m.section==='custom'?'· 직접 입력 중':''}</summary><div class="fields">${h.field('materials.0.kgm','자재 1m의 무게 (kg/m)')}${h.field('materials.0.face','정면 폭 (mm)')}${h.field('materials.0.depth','옆면 폭 (mm)')}${h.field('materials.0.t1','관·웹 두께 (mm)',{nullable:true})}${h.field('materials.0.t2','H형강 날개 두께 (mm)')}${h.field('materials.0.grade','재질',{type:'text'})}${h.field('materials.0.finish','표면처리',{type:'text'})}</div><label class="field">전체 프레임에 적용할 자재<select id="frame-basic-material">${h.materialOptions().map(([id,name])=>`<option value="${esc(id)}">${esc(name)}</option>`).join('')}</select></label>${h.button('apply-basic-material','전체 프레임에 선택 자재 적용')}<p class="hint">추가 지주와 각 부재의 위치·방향은 유지합니다.</p></details><details id="frame-purchase-settings"><summary>구매 길이·자재 가격 ${m.stockMode==='mixed'?'· 혼합 길이 사용 중':''}</summary><div class="fields">${h.select('materials.0.stockMode','구매 길이 사용 방식',[['selected','한 가지 길이 사용'],['mixed','등록한 길이 혼합 사용']])}${h.select('materials.0.selectedLength','구매할 자재 한 본의 길이',m.stocks.map(x=>[x.length,fmt(x.length,0)+' mm']),{disabled:m.stockMode==='mixed'})}${price}</div>${purchasing?'<p class="frame-guidance" id="frame-purchase-guidance">'+esc(purchasing)+'. 구매·절단 계획에서 확인하세요.</p>':''}<p class="hint">가격을 입력하지 않아도 수량과 중량은 계산됩니다.</p></details><button type="button" class="button secondary" data-frame-detail="design">부재별 규격·위치 상세 입력</button></section>${drawing()}</div>${extraView(p,h)}<details id="frame-accessory-settings" class="frame-wizard-panel"><summary>판재·부속품 ${p.accessories.length}종과 작업 비용</summary>${h.accessoriesView()}</details><details class="frame-wizard-panel" id="frame-cut-settings"><summary>절단·이음 조건</summary><div class="fields">${h.field('cut.kerf','톱날 손실 (mm/회)')}${h.field('cut.endTrim','양끝 정리 (mm/본)')}${h.field('cut.overlap','이음부 겹침 (mm)')}${h.select('cut.precision','제작 길이 단위',[[0,'원치수 유지'],[0.1,'0.1mm 반올림'],[1,'1mm 반올림']])}${h.select('cut.objective','혼합 구매 목표',[['bars','본수 줄이기'],['waste','잔재 비율 줄이기'],['cost','비용 줄이기']])}</div></details><div class="frame-wizard-actions"><button id="frame-prev" type="button" class="button secondary">← 크기 수정</button><button id="frame-next" type="button" class="button primary">필요한 자재 확인하기 →</button></div>`;
  }
  function resultView(p,r,h){return `<section class="frame-overview-card"><p class="eyebrow">입력 조건의 제작 계획</p><h2>필요한 자재와 중량을 확인하세요.</h2><div class="frame-size-summary" id="frame-result-size"></div><div class="frame-simple-totals"><div><span>완성품 대당 중량</span><strong id="frame-result-weight">—</strong></div><div><span>신규 원자재 구매</span><strong id="frame-result-purchase">—</strong></div><div><span>입력 금액 · 세율 포함</span><strong id="frame-result-cost">—</strong></div></div><p class="frame-guidance" id="frame-result-status"></p><div id="frame-mass-breakdown"></div><p class="hint">등록하지 않은 제품·지주·부속품 중량은 포함되지 않습니다. 부재·절단 물량 산출이며 구조 안전 검토는 별도입니다.</p><div class="frame-result-actions">${h.button('xlsx','엑셀 저장')}${h.button('csv','CSV 저장')}${h.button('json','설정 저장')}${h.button('print','인쇄 · PDF')}<button id="frame-to-foundation" type="button" class="button primary" ${window.parent===window?'hidden':''}>기초에 적용할 값 확인 →</button></div></section>${drawing()}<details class="frame-wizard-panel frame-result-details"><summary>부재 산출표·중량·견적 자세히 보기</summary>${h.reportView()}</details><div class="frame-wizard-actions"><button id="frame-prev" type="button" class="button secondary">← 규격·보강재 수정</button><button type="button" class="button secondary" data-frame-step="1">크기 다시 수정</button><button type="button" class="button secondary" data-frame-detail="purchase">구매·절단 계획 상세 보기</button></div>`;}
  function view(p,r,h){helpers=h;if(projectId!==p.id){projectId=p.id;step=1;}return step===1?sizeView(p,r,h):step===2?memberView(p,r,h):resultView(p,r,h);}
  function updated(p,r){
    const mode=p.ui?.inputMode==='detailed'?'detailed':'simple',simple=mode==='simple';document.body.classList.add('frame-easy-app');document.body.dataset.mode=mode;
    document.querySelector('.tabs').hidden=simple;$('metrics').hidden=simple;$('frame-wizard-nav').hidden=!simple;$('frame-wizard-progress').hidden=!simple;
    for(const name of ['simple','detailed'])$('frame-input-'+name).setAttribute('aria-pressed',String(name===mode));document.querySelector('.frame-mode-buttons').dataset.mode=mode;
    $('frame-mode-note').textContent=simple?'크기 → 규격·보강 → 결과 순서로 입력합니다. 상세 입력으로 바꿔도 작성한 값은 유지됩니다.':'면별 자재·재고·판재·비용·절단·출력을 직접 수정합니다. 간편 입력으로 돌아가도 개별 설정은 유지됩니다.';
    const titles=['어떤 모양으로 만들까요?','그림을 보며 보강을 조절하세요.','필요한 자재와 무게를 확인하세요.'];
    $('frame-wizard-title').textContent=simple?titles[step-1]:'제작 조건을 직접 입력하세요.';
    $('frame-step-description').textContent=simple?['모양을 고르고 가로·세로·수량만 입력하세요.','주황색은 세로, 보라색은 가로 보강입니다.','대당 무게와 구매 수량을 확인한 뒤 기초에 연결하세요.'][step-1]:'아래 작업 항목을 선택해 기존 조건을 수정할 수 있습니다.';
    $('frame-workflow-count').textContent=simple?String(step).padStart(2,'0')+' / 03':'상세 입력';
    for(let i=1;i<=3;i++){const b=$('frame-step-'+i);b.setAttribute('aria-current',i===step?'step':'false');b.classList.toggle('complete',i<step);}
    $('frame-wizard-progress').dataset.step=String(step);
    const set=(id,text)=>{if($(id))$(id).textContent=text;};
    set('frame-depth-tie-summary',!r?'입력값을 확인하면 자동 연결재를 표시합니다.':r.connectorWarnings.length?'앞뒤 보강 위치 확인 필요 · '+r.connectorWarnings.join(' · '):r.general.verticalDepthTies?`위·아래 앞뒤 연결재 ${r.depthConnectors.length}개/대 자동 포함 · 제작 전체 ${r.depthConnectors.length*r.general.quantity}개`:'앞뒤 연결재 자동 추가 꺼짐 · 아래 설정에서 변경할 수 있습니다.');
    set('frame-depth-tie-info',!r?'입력 오류를 수정하면 연결재 물량을 표시합니다.':!r.general.verticalDepthTies?'자동 추가 꺼짐 · 직접 등록한 연결재를 사용하는 경우 유지하세요.':`앞뒤 세로 보강재 위·아래 연결재 자동 추가: ${r.depthConnectors.length}개/대 · 제작 전체 ${r.depthConnectors.length*r.general.quantity}개. 앞뒤 중심선이 일치하는 부재에 앞면 세로재와 같은 자재를 사용합니다. 같은 연결재를 추가 부재로 직접 등록했다면 자동 추가를 꺼서 중복을 피하세요.`+(r.connectorWarnings.length?' '+r.connectorWarnings.join(' · '):''));
    if(simple&&p.cabinet.enabled)for(const key of ['width','height']){const input=$('frame-field-general-'+key);if(input&&input.disabled)input.value=Number.isFinite(p.cabinet[key]*p.cabinet[key==='width'?'columns':'rows'])?p.cabinet[key]*p.cabinet[key==='width'?'columns':'rows']:'';}
    if(simple&&step===2){const input=$('frame-field-materials-0-section');if(input)input.value=p.materials[0].section;}
    if($('frame-simple-diagram'))$('frame-simple-diagram').innerHTML=r&&helpers?helpers.svg(r.panels.front,'front'):'<p>입력 오류를 수정하면 배치도가 표시됩니다.</p>';
    set('frame-live-size',r?`${fmt(r.general.width)} × ${fmt(r.general.height)}${r.general.planes===2?' × '+fmt(r.general.depth):''} mm · 제작 ${r.general.quantity}대`:'크기·규격 입력을 확인하세요.');
    set('frame-result-size',r?`${fmt(r.general.width/1000,3)} × ${fmt(r.general.height/1000,3)} m · ${r.general.planes===2?'깊이형':'단면'} · 제작 ${r.general.quantity}대`:'입력 오류 · 결과 확인 필요');
    set('frame-result-weight',r?fmt(r.totalWeight/r.general.quantity,3)+' kg':'—');set('frame-result-purchase',r?fmt(r.purchase.purchaseCount,0)+'본':'—');set('frame-result-cost',r?(r.costs.total===null?'단가 미입력 · 미확정':fmt(r.costs.total,0)+'원'):'입력 확인 필요');
    set('frame-result-status',r?.connectorWarnings.length?'앞뒤 세로 보강재 위치 확인 필요 · '+r.connectorWarnings.join(' · '):!r?'입력 오류를 수정하면 결과가 다시 표시됩니다.':r.purchase.status!=='ready'?'절단 조각 미충족 · 구매·연장 계획을 확인하세요.':'입력한 조건의 제작 물량을 계산했습니다. 구조 안전 판정은 별도입니다.');
    set('frame-mass-breakdown',r?`대당 프레임 ${fmt(r.frameWeight/r.general.quantity,3)} kg · 판재·부속 ${fmt(r.accessoryWeight/r.general.quantity,3)} kg · 캐비닛 ${fmt(r.cabinetWeight/r.general.quantity,3)} kg · 기타 제품·장비 ${fmt((r.equipmentWeight-r.cabinetWeight)/r.general.quantity,3)} kg. 제작 전체 ${fmt(r.totalWeight,3)} kg`:'');
    for(const id of ['frame-next','frame-to-foundation'])if($(id))$(id).disabled=!r;
  }
  function setMode(mode,tab){if(!['simple','detailed'].includes(mode))return false;if(api.hasCountErrors()){api.focusError();return false;}transitioning=true;try{api.setInputMode(mode);if(mode==='detailed'&&tab)api.showTab(tab);}finally{transitioning=false;}return true;}
  function showStep(next,{force=false,focus=true}={}){
    if(![1,2,3].includes(next))return false;
    api.flush();if(!force&&(api.hasCountErrors()||next>step&&!api.getResult())){api.focusError();return false;}
    if(next===3&&!api.getResult()){api.focusError();return false;}step=next;api.refresh();if(focus){$('frame-step-'+step).focus({preventScroll:true});$('frame-workflow-heading').scrollIntoView({block:'start',behavior:'auto'});}return true;
  }
  function revealIssue(issue){if(transitioning)return;const path=issue.paths?.[0]||issue.counts?.[0]||'';step=/^general\.|^cabinet\./.test(path)?1:2;api.refresh();}
  function focusPart(part){
    if(getMode()!=='simple'||!['front.vertical','front.horizontal','left.vertical','left.horizontal','material','tie'].includes(part))return false;
    if(step!==2&&!showStep(2,{focus:false}))return false;
    const input=part==='material'?$('frame-field-materials-0-section'):part==='tie'?$('frame-field-general-verticalDepthTies'):document.querySelector(`[data-count="${part}"]`);
    if(!input)return false;
    for(let node=input.parentElement;node;node=node.parentElement)if(node.tagName==='DETAILS')node.open=true;
    input.focus({preventScroll:true});input.scrollIntoView({block:'nearest',behavior:'auto'});window.Frame3D?.selectPart(part);return true;
  }
  document.addEventListener('focusin',event=>{
    if(getMode()!=='simple')return;
    const part=event.target.dataset.count||event.target.dataset.frameCountAdjust||(event.target.dataset.path==='materials.0.section'?'material':event.target.dataset.path==='general.verticalDepthTies'?'tie':'');
    document.querySelectorAll('[data-part-field]').forEach(node=>node.classList.toggle('is-active',node.dataset.partField===part));
    window.Frame3D?.selectPart(part);
  });
  document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;
    if(b.dataset.frameShape){const input=$('frame-field-general-planes');if(input){input.value=b.dataset.frameShape;input.dispatchEvent(new Event('input',{bubbles:true}));$('frame-field-general-'+(b.dataset.frameShape==='2'?'depth':'width'))?.focus({preventScroll:true});}}
    if(b.dataset.frameCountAdjust){const input=document.querySelector(`[data-count="${b.dataset.frameCountAdjust}"]`);if(!input)return;const value=Number(input.value);if(input.value===''||!Number.isInteger(value)||value<0||value>100){input.focus();return;}input.value=String(Math.max(0,Math.min(100,value+Number(b.dataset.delta))));input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));window.Frame3D?.selectPart(b.dataset.frameCountAdjust);}
    if(b.id==='frame-input-simple')setMode('simple');if(b.id==='frame-input-detailed')setMode('detailed');
    if(/^frame-step-[123]$/.test(b.id))showStep(Number(b.id.slice(-1)));if(b.id==='frame-next')showStep(step+1);if(b.id==='frame-prev')showStep(step-1);if(b.dataset.frameStep)showStep(Number(b.dataset.frameStep));if(b.dataset.frameDetail)setMode('detailed',b.dataset.frameDetail);
    if(b.id==='frame-to-foundation'){api.flush();const transfer=window.parent.document.getElementById('suite-transfer');if(api.getResult()&&transfer&&!transfer.disabled)transfer.click();}
  });
  $('frame-wizard-nav').addEventListener('keydown',event=>{const button=event.target.closest('button');if(!button||!['ArrowRight','ArrowLeft','Home','End'].includes(event.key))return;event.preventDefault();const current=Number(button.id.slice(-1)),next=event.key==='Home'?1:event.key==='End'?3:(current-1+(event.key==='ArrowRight'?1:2))%3+1;showStep(next);});
  window.FrameUX={view,updated,setMode,showStep,revealIssue,focusPart,getState:()=>({mode:getMode(),step})};api.refresh();
})();
